// documentation for more info.
func (u *EntityLinkUpsertBulk) Update(set func(*EntityLinkUpsert)) *EntityLinkUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&EntityLinkUpsert{UpdateSet: update})
	}))
	return u
}

